import hashlib
import json
import os
from pathlib import Path
import subprocess

root = Path(__file__).resolve().parent
binaries = {
    'before': '/private/tmp/cryptty-before-coalescing',
    'coalesced': '/Users/even/cryptty/target/release/cryptty',
}
env = os.environ.copy()
env['XDG_CONFIG_HOME'] = str(root / 'config')
records = {'binaries': {k: hashlib.sha256(Path(v).read_bytes()).hexdigest()
                        for k, v in binaries.items()}, 'runs': []}
for kind, trials in [('throughput', 3), ('latency', 2)]:
    for trial in range(trials):
        order = list(binaries)
        if trial % 2:
            order.reverse()
        for name in order:
            stem = f'{kind}-{name}-{trial}'
            result = root / f'{stem}.json'
            command = [binaries[name], '--renderer', 'gpu', '--',
                       '/Users/even/.venv/bin/python', str(root/'workload.py'),
                       str(result), '--lines', '262144']
            if kind == 'latency':
                command.append('--latency')
            print('START', stem, flush=True)
            with (root/f'{stem}.log').open('w') as log:
                child = subprocess.Popen(command, env=env, stdout=log, stderr=log)
                try:
                    status = child.wait(timeout=90)
                except BaseException:
                    child.terminate()
                    try:
                        child.wait(timeout=5)
                    except subprocess.TimeoutExpired:
                        child.kill()
                        child.wait()
                    raise
            data = json.loads(result.read_text()) if result.exists() else {}
            if status or not data or 'error' in data:
                raise RuntimeError((stem, status, data))
            records['runs'].append(dict(name=name, kind=kind, trial=trial, data=data))
            (root/'results.json').write_text(json.dumps(records, indent=2))
            print('DONE', stem, flush=True)
